/// MessageMeta travels with every bus message.
///
/// Kept deliberately small. Each field earns its place by being needed to
/// route, correlate or audit a message; anything a handler could look up
/// instead does not belong here, because the envelope is paid for on every
/// single message.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct MessageMeta {
    /// Unique per message. The idempotency key: a handler that has seen this id
    /// may drop the message.
    #[prost(string, tag = "1")]
    pub message_id: ::prost::alloc::string::String,
    /// Constant across every message caused by one originating action, so an
    /// operator can follow a broker sync all the way to a position update.
    #[prost(string, tag = "2")]
    pub correlation_id: ::prost::alloc::string::String,
    /// The message_id of the message that caused this one. correlation_id gives
    /// the set; causation_id gives the shape of the tree inside it.
    #[prost(string, tag = "3")]
    pub causation_id: ::prost::alloc::string::String,
    /// The instance that published this. Provenance, and the reply address for a
    /// request.
    #[prost(string, tag = "4")]
    pub publisher_instance_id: ::prost::alloc::string::String,
    /// The topic this was published on. Present so a message stays interpretable
    /// once it has been captured away from its subscription.
    #[prost(string, tag = "5")]
    pub topic: ::prost::alloc::string::String,
    /// Publisher wall clock at publish, epoch nanoseconds UTC. Observation time,
    /// not event time: when something happened in the world belongs on the
    /// payload, because only the payload knows what "happened" means.
    #[prost(string, tag = "6")]
    pub schema_version: ::prost::alloc::string::String,
    #[prost(int64, tag = "7")]
    pub published_at_ns: i64,
    /// Set on a command sent for a person: whose it is, so the store can record
    /// who made the change. Deployment-local subject.
    #[prost(string, tag = "8")]
    pub acting_for_subject: ::prost::alloc::string::String,
    /// Set on a read: the accounts the publishing plugin may read. A core store
    /// answers only for these.
    #[prost(string, repeated, tag = "9")]
    pub account_scope: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    /// Set by the sidecar on every query it sends for a plugin, beside
    /// account_scope, and never by a core component (W4.11): the scope
    /// applies, so an empty one is nothing. A store answers a query carrying
    /// it whose scope is empty with nothing, and refuses one naming an account
    /// outside the scope.
    #[prost(bool, tag = "10")]
    pub account_scope_applies: bool,
}
